__NUXT_JSONP__("/ar/how-to-apply/student-visa-f1/change-of-status", {data:[{details:{slug:"ar",pageTitle:"تغيير حالة الفيزا | Mentor Language Institute",pageDescription:"نشكر لك إهتمامك بالإلتحاق بمعهد مينتور",title:"تغيير حالة الفيزا",image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fchange-of-status.jpg",subtitle:["نشكر لك إهتمامك بالإلتحاق بمعهد مينتور\u003Cbr \u002F\u003Eهذه الصفحة للمتواجدين حاليا في الولايات المتحدة لكن لايحملون فيزا الطالب F1 ويرغبون بتحويل فيزتهم إلى فيزا طالب","إذا كنت ترغب التقدم تتبع الخطوات التالية"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fapply-now-ar.png",link:"\u002Far\u002Fadmission"}},applicationSteps:{title:"خطوات الأبلكيشن",description:["خطوات الأبلكيشن تعتد على العديد من المعايير منها: موطن الشخص, جنسيته, الدورة المتقدم لها, نوع الفيزا المطلوبة .. الخ. موظفينا سيسعدون بخدمتك و إرشادك بالخطوات الملائمة بناء على حالتك"]},needHelp:{title:"تحتاج المساعدة؟ إسألنا",description:["قوانين الفيزا و خطوات الأبلكيشن مختلفة بناء على حالتك الحالية\u003Cbr \u002F\u003Eإن احتجت المزيد من التوضيح قبل البدء بالتقديم, لاتتردد بالتواصل معنا. لدينا موظفين يتحدثون ثمانية لغات بطلاقة"]},contactUs:{image:"\u002Fimages\u002Fhow-to-apply\u002Fchange-of-status\u002Fcontact-us-ar.png",link:"\u002Far\u002Fcontact",title:"اتصل بنا",lists:[{campus:"مقر ويستوود",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"Tel:310⁻887⁻0777"},{campus:"مقر هوليوود",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"Tel:323⁻870⁻7102"}]},dir:"\u002Fchange-of-status",path:"\u002Fchange-of-status\u002Far",extension:".json",createdAt:"2026-10-22T16:31:28.779Z",updatedAt:"2025-05-26T12:06:27.712Z"}}],fetch:{},mutations:void 0});